SELECT toDate(timestamp) AS Day, uniqExactIf(person_id, event = '$pageview' AND (properties.surface IS NULL OR properties.surface = 'web') AND (properties.environment IS NULL OR properties.environment = 'production') AND match(toString(properties.$current_url), '^https://(www[.])?ypr[.]app(/|$)')) AS Visitors, uniqExactIf(distinct_id, event='signup_verified' AND (properties.environment = 'production' AND properties.product = 'studio')) AS Signups, uniqExactIf(person_id, (event IN ('studio_screen_viewed','native_app_opened','native_screen_viewed','native_app_active','native_project_created','native_media_imported','native_export_completed','native_action_finished') OR event='product_action_completed') AND (properties.environment = 'production' AND properties.product = 'studio')) AS Active, uniqExactIf(person_id, properties.surface='macos' AND (event IN ('studio_screen_viewed','native_app_opened','native_screen_viewed','native_app_active','native_project_created','native_media_imported','native_export_completed','native_action_finished') OR event='product_action_completed') AND (properties.environment = 'production' AND properties.product = 'studio')) AS Mac FROM events WHERE {filters} GROUP BY Day ORDER BY Day LIMIT 1000
